package main

import (
	"os"
	"path/filepath"
	"testing"
)

func TestMetricsScopeAndDecisions(t *testing.T) {
	root := t.TempDir()
	files := map[string]string{
		"internal/demo/real.go":      "package demo\nimport \"strings\"\n// Trim returns a nonempty string.\nfunc Trim(s string) string {\n if s == \"\" || strings.TrimSpace(s) == \"\" {\n  return \"empty\"\n }\n return s\n}\n",
		"internal/demo/real_test.go": "package demo\nfunc TestIgnored() {}\n",
		"pkg/generated.go":           "// Code generated by test. DO NOT EDIT.\npackage generated\nfunc Ignored() {}\n",
		"cmd/metrics/main.go":        "package main\nfunc Ignored() {}\n",
		"tools/dtomap/main.go":       "package main\nfunc Ignored() {}\n",
	}
	for name, contents := range files {
		path := filepath.Join(root, name)
		if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(contents), 0644); err != nil {
			t.Fatal(err)
		}
	}
	r, err := measure(root)
	if err != nil {
		t.Fatal(err)
	}
	if r.Summary.Files != 1 || r.Summary.Functions != 1 || r.Summary.CyclomaticMax != 3 || r.PackageFanOut["internal/demo"] != 1 {
		t.Fatalf("unexpected metrics: %+v", r)
	}
	if r.Summary.SourceLines != 9 || r.Summary.CommentLines != 1 || r.Summary.CodeLines != 8 {
		t.Fatalf("unexpected lines: %+v", r.Summary)
	}
}
